//! Dev harness: `cargo run -p kladde-hex --example hex_demo [file]`; without a file, 4 KiB of generated bytes.

use std::io::Write;
use std::path::PathBuf;

use kladde_core::{Document, OpenMode, OpenOptions, Progress};
use kladde_hex::{HexConfig, HexEvent, HexMode, HexState, HexTheme, TextColumn};

struct Demo {
    doc: Document,
    state: HexState,
    cfg: HexConfig,
    dark: bool,
    big_endian: bool,
    goto: String,
    errors: Vec<String>,
    // Keeps the generated sample file alive while it is open.
    _sample: Option<tempfile::NamedTempFile>,
}

impl eframe::App for Demo {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.doc.poll_line_index();
        egui::SidePanel::right("controls").min_width(300.0).show(ctx, |ui| self.controls(ui));
        egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx, |ui| {
            let theme = if self.dark { HexTheme::dark() } else { HexTheme::light() };
            let out = kladde_hex::show(ui, egui::Id::new("hex"), &mut self.doc, &mut self.state, &self.cfg, &theme);
            self.errors.extend(out.events.into_iter().map(|HexEvent::Error(e)| e));
        });
    }
}

impl Demo {
    fn controls(&mut self, ui: &mut egui::Ui) {
        ui.heading("Kladde hex demo");
        ui.label(format!("{} bytes, source {:?}", self.doc.len(), self.doc.source_kind()));
        let sel = self.state.selection();
        ui.label(format!("cursor {:#X}, selection {:#X}..{:#X}", self.state.cursor(), sel.start, sel.end));
        ui.horizontal(|ui| {
            ui.selectable_value(&mut self.cfg.mode, HexMode::Hex, "Hex");
            ui.selectable_value(&mut self.cfg.mode, HexMode::Binary, "Binary");
        });
        ui.horizontal(|ui| {
            ui.selectable_value(&mut self.cfg.text, TextColumn::Ascii, "ASCII");
            ui.selectable_value(&mut self.cfg.text, TextColumn::Latin1, "Latin-1");
            ui.selectable_value(&mut self.cfg.text, TextColumn::Utf8, "UTF-8");
        });
        ui.add(egui::Slider::new(&mut self.cfg.bytes_per_row, 1..=64).text("bytes per row"));
        ui.horizontal(|ui| {
            ui.label("group");
            [1u8, 2, 4, 8].iter().for_each(|&g| {
                ui.selectable_value(&mut self.cfg.group, g, g.to_string());
            });
        });
        ui.add(egui::Slider::new(&mut self.cfg.font_size, 8.0..=32.0).text("font size"));
        let mut insert = self.state.insert_mode();
        if ui.checkbox(&mut insert, "Insert mode (Insert key)").changed() {
            self.state.set_insert_mode(insert);
        }
        ui.checkbox(&mut self.dark, "Dark theme");
        ui.horizontal(|ui| {
            ui.label("Go to hex offset");
            let enter =
                ui.text_edit_singleline(&mut self.goto).lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter));
            if enter {
                match u64::from_str_radix(self.goto.trim().trim_start_matches("0x"), 16) {
                    Ok(off) => self.state.goto(&self.doc, off),
                    Err(e) => self.errors.push(format!("bad offset: {e}")),
                }
            }
        });
        ui.horizontal(|ui| {
            if ui.add_enabled(self.doc.can_undo(), egui::Button::new("Undo")).clicked() {
                self.doc.undo();
            }
            if ui.add_enabled(self.doc.can_redo(), egui::Button::new("Redo")).clicked() {
                self.doc.redo();
            }
        });
        ui.separator();
        kladde_hex::show_inspector(ui, &self.doc, &self.state, &mut self.big_endian);
        ui.separator();
        ui.label("Errors:");
        self.errors.iter().rev().take(10).for_each(|e| {
            ui.colored_label(egui::Color32::LIGHT_RED, e);
        });
    }
}

fn sample_file() -> std::io::Result<tempfile::NamedTempFile> {
    let mut file = tempfile::Builder::new().suffix(".bin").tempfile()?;
    let text = "Kladde hex demo: ASCII, Latin-1 caf\u{e9}, UTF-8 \u{20ac} \u{1f600}\n".as_bytes();
    let bytes: Vec<u8> = text.iter().copied().chain((0..4096 - text.len()).map(|i| (i * 7 % 256) as u8)).collect();
    file.write_all(&bytes)?;
    file.flush()?;
    Ok(file)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let arg = std::env::args_os().nth(1).map(PathBuf::from);
    let sample = match arg {
        Some(_) => None,
        None => Some(sample_file()?),
    };
    let path = arg.or_else(|| sample.as_ref().map(|s| s.path().to_path_buf())).expect("file argument or sample");
    let opts = OpenOptions { mode: OpenMode::Binary, read_only: false, no_lock: false };
    let doc = Document::open(&path, &opts, &Progress::new())?;
    let demo = Demo {
        doc,
        state: HexState::new(),
        cfg: HexConfig { bytes_per_row: 16, group: 4, mode: HexMode::Hex, text: TextColumn::Utf8, font_size: 14.0 },
        dark: true,
        big_endian: false,
        goto: String::new(),
        errors: Vec::new(),
        _sample: sample,
    };
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size([1280.0, 720.0]),
        ..Default::default()
    };
    eframe::run_native("kladde-hex demo", options, Box::new(|_cc| Ok(Box::new(demo))))?;
    Ok(())
}
